from pathlib import Path
from typing import Any, Optional

import polars as pl
import torch

from sglang.srt.debug_utils.dump_loader import ValueWithMeta


def _render_polars_as_text(df: pl.DataFrame, *, title: Optional[str] = None) -> str:
    """Render a Polars DataFrame as a plain-text table.

    The output always contains every column name (as a header row) followed by
    one line per row. When ``title`` is provided it is prepended. Empty
    DataFrames (no rows and/or no columns) are handled without error.
    """
    lines: list[str] = []
    if title is not None:
        lines.append(title)

    columns: list[str] = list(df.columns)
    lines.append(" | ".join(columns))

    for row in df.iter_rows():
        lines.append(" | ".join("" if value is None else str(value) for value in row))

    return "\n".join(lines)


def _extract_parallel_info(row_data: dict[str, Any], info: dict[str, Any]) -> None:
    """Write parallel-dimension entries from ``info`` into ``row_data`` in place.

    For each ``<base>_rank`` key in ``info`` that has a matching ``<base>_size``
    key, sets ``row_data[base] = "{rank}/{size}"`` (e.g. ``"tp": "0/2"``). Does
    nothing when ``info`` is empty or contains an ``"error"`` key. ``_rank`` keys
    without a corresponding ``_size`` key are skipped.
    """
    if not info or "error" in info:
        return

    for key in info:
        if not key.endswith("_rank"):
            continue
        base = key[: -len("_rank")]
        size_key = f"{base}_size"
        if size_key not in info:
            continue
        row_data[base] = f"{info[key]}/{info[size_key]}"


def _collect_rank_info(
    df: pl.DataFrame, dump_dir: Path
) -> Optional[list[dict[str, Any]]]:
    """Collect per-rank parallel topology info from ``input_ids`` dump files.

    Returns ``None`` when no rows named ``"input_ids"`` exist. Otherwise returns
    a list of dicts (deduplicated so there is at most one entry per rank), each
    containing ``"rank"`` and any parallel dimension entries (e.g. ``"tp"``,
    ``"pp"``) read from ``sglang_parallel_info`` in the file metadata.
    """
    if "name" not in df.columns:
        return None

    matching = df.filter(pl.col("name") == "input_ids")
    if matching.height == 0:
        return None

    dump_dir = Path(dump_dir)
    result: list[dict[str, Any]] = []
    seen_ranks: set[Any] = set()

    for row in matching.to_dicts():
        rank = row.get("rank")
        if rank in seen_ranks:
            continue
        seen_ranks.add(rank)

        row_data: dict[str, Any] = {"rank": rank}
        loaded = ValueWithMeta.load(dump_dir / row["filename"])
        info = loaded.meta.get("sglang_parallel_info", {})
        if isinstance(info, dict):
            _extract_parallel_info(row_data, info)
        result.append(row_data)

    return result


def _collect_input_ids_and_positions(
    df: pl.DataFrame, dump_dir: Path, *, tokenizer: Any = None
) -> Optional[list[dict[str, Any]]]:
    """Collect input token ids and positions from dump files.

    Returns ``None`` when no rows named ``"input_ids"`` or ``"positions"`` exist.
    Otherwise returns a list of dicts, one per ``(step, rank)`` pair, each with
    ``"step"``, ``"rank"``, ``"num_tokens"`` (int), ``"input_ids"`` (str) and
    ``"positions"`` (str). When ``tokenizer`` is given, each dict additionally
    contains ``"decoded_text"`` = ``repr(tokenizer.decode(ids, ...))``.
    """
    if "name" not in df.columns:
        return None

    matching = df.filter(pl.col("name").is_in(["input_ids", "positions"]))
    if matching.height == 0:
        return None

    dump_dir = Path(dump_dir)

    # Group filenames by (step, rank) pair, keyed by tensor name.
    grouped: dict[tuple[Any, Any], dict[str, str]] = {}
    order: list[tuple[Any, Any]] = []
    for row in matching.to_dicts():
        key = (row.get("step"), row.get("rank"))
        if key not in grouped:
            grouped[key] = {}
            order.append(key)
        grouped[key][row["name"]] = row["filename"]

    result: list[dict[str, Any]] = []
    for step, rank in sorted(order, key=lambda k: (k[0], k[1])):
        files = grouped[(step, rank)]

        ids_list = _load_tensor_as_list(dump_dir, files.get("input_ids"))
        positions_list = _load_tensor_as_list(dump_dir, files.get("positions"))

        record: dict[str, Any] = {
            "step": step,
            "rank": rank,
            "num_tokens": len(ids_list),
            "input_ids": str(ids_list),
            "positions": str(positions_list),
        }
        if tokenizer is not None:
            record["decoded_text"] = repr(
                tokenizer.decode(ids_list, skip_special_tokens=False)
            )
        result.append(record)

    return result


def _load_tensor_as_list(dump_dir: Path, filename: Optional[str]) -> list:
    if filename is None:
        return []
    loaded = ValueWithMeta.load(dump_dir / filename)
    value = loaded.value
    if isinstance(value, torch.Tensor):
        return value.flatten().tolist()
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return list(value)
