        ids_list = _load_tensor_as_list(dump_dir, files.get("input_ids"))
        positions_list = _load_tensor_as_list(dump_dir, files.get("positions"))

        record: dict[str, Any] = {
            "step": step,
            "rank": rank,
            "num_tokens": len(ids_list),
            "input_ids": str(ids_list),
