def _load_tensor_as_list(dump_dir: Path, filename: Optional[str]) -> list:
    if filename is None:
        return []
    loaded = ValueWithMeta.load(dump_dir / filename)
    value = loaded.value
    if isinstance(value, torch.Tensor):
        return value.flatten().tolist()
    if value is None:
        return []
    if isinstance(value, list):
        return value
    return list(value)
